            padded_data.data() + i,
            encrypted_data.data() + i,
            AES_BLOCK_SIZE,
            &aes_key,
            iv_copy.data(),
            AES_ENCRYPT
        );
    }

    return {encrypted_data, iv, std::vector<unsigned char>(key.begin(), key.begin() + AES_BLOCK_SIZE)};
}
